// === Tab: mySketch ===
let musicAnalyzer;
var bass_p = [];
var mid_p = [];
var treble_p = [];
var noiseScale = 800;
let font, fontsize = 15;
let iMid = 0;
let iBass = 0;
let iTreble = 0;

let colorCanvas = 0; //change the canvas color: 0 is black, 255 is white

//Change the color for the bass tones
let R1 = 6;
let G1 = 129;
let B1 = 144;

//Change the color for mid tones
let R2 = 84;
let G2 = 62;
let B2 = 199;

//Change the color for treble
let R3 = 198;
let G3 = 27;
let B3 = 136;

//Change the color for the octaves (background effect)
let Rbg = 15;
let Gbg = 100;
let Bbg = 80;

function keyPressed() {
	if (key == 's') saveImage(); //Press S to save your image
}

function preload() {
	soundFormats('mp3', 'ogg');
	//music = loadSound('https://openprocessing.org/sketch/730192/files/Nexxi_Kicks_-_The_Move_DEMO.mp3'); //Load your own track to paint with
	music = loadSound('https://openprocessing.org/sketch/730192/files/schubert.mp3');
	//music = loadSound('https://openprocessing.org/sketch/730192/files/Chopin_-_Demo.mp3');
	font = loadFont("https://openprocessing.org/sketch/730192/files/Roboto-Regular.ttf");
}

function setup() {
	music.setVolume(1);
	music.play();
	musicAnalyzer = new p5.FFT();
	musicAnalyzer.setInput(music);
	createCanvas(1280, 720);
	textFont(font);
	textSize(fontsize);
	textAlign(LEFT, CENTER);
	background(colorCanvas);
}

function draw() {

	let musicAnalyzed = musicAnalyzer.analyze();

	var bass = musicAnalyzer.getEnergy("bass");
	var mid = musicAnalyzer.getEnergy("mid");
	var treble = musicAnalyzer.getEnergy("treble");

	var soundArray = [bass, mid, treble];

	let spectrum = musicAnalyzer.analyze();

	noStroke();
	smooth();

	if(bass > 100){
					bass_p[iBass] = new Particle(random(0, width),random(0,height));
					iBass++;
	}

	if(mid > 10){
					mid_p[iMid] = new Particle(random(0, width),random(0,height));
					iMid++;
	}

	if (treble > 0.1) {
		treble_p[iTreble] = new Particle(random(0, width), random(0, height));
		iTreble++;
	}

	if (bass_p !== undefined || bass_p.length != 0) {
		for (var bassx = 0; bassx < iBass; bassx++) {
			var radius = map(bassx, 0, 300, 1, 2);

			if(bass > 100){
				fill(color(R1 * (bass/250), G1 * (bass/250), B1 * (bass/250), 75 + bass));
				bass_p[bassx].move(bass/20);
				bass_p[bassx].display(bass/10);
				bass_p[bassx].checkEdge();
			}
		}
	}

	if (mid_p !== undefined || mid_p.length != 0) {
		for (var midx = 0; midx < iMid; midx++) {
			var radius = map(midx, 0, 300, 1, 2);

			if(mid > 10){
				fill(color(R2 * (mid/200), G2 * (mid/200), B2 * (mid/200), 75 + mid));
				mid_p[midx].move(mid/20);
				mid_p[midx].display(mid/10);
				mid_p[midx].checkEdge();
			}
		}
	}

	if (treble_p !== undefined || treble_p.length != 0) {
		for (var treblex = 0; treblex < iTreble; treblex++) {
			var radius = map(treblex, 0, 500, 1, 2);

			if(treble > 30){
				fill(color(R3 * (treble/200), G3 * (treble/200), B3 * (treble/200), 75 + treble));
				treble_p[treblex].move(treble/10);
				treble_p[treblex].display(treble/15);
				treble_p[treblex].checkEdge();
			}
		}
	}
}

function Particle(x, y) {
	this.dir = createVector(0, 0);
	this.vel = createVector(0, 0);
	this.pos = createVector(x, y);
	this.speed = 0.4;

	this.move = function(boost) {
		var angle = noise(this.pos.x / (noiseScale - boost), this.pos.y / (noiseScale - boost)) * TWO_PI * noiseScale;
		this.dir.x = cos(angle);
		this.dir.y = sin(angle);
		this.vel = this.dir.copy();
		this.vel.mult(this.speed);
		this.pos.add(this.vel);
	}

	this.checkEdge = function() {
		if (this.pos.x > width || this.pos.x < 0 || this.pos.y > height || this.pos.y < 0) {
			this.pos.x = random(0, width);
			this.pos.y = random(0, height);
		}
	}

	this.display = function(r) {
		ellipse(this.pos.x, this.pos.y, 0 + r, 0 + r);
	}

}

function saveImage() {
	noLoop();
	fill(255);
	text("Painted using: " + music.file, 10, 700);
	save('Music Painting - ' + music.file + '.png');
	music.pause();
}

